import{_ as d,o as r,c as a,a3 as o}from"./chunks/framework.CqzWVxDX.js";const e="/ems_simulate/assets/iec104-operation.K0ltCEBn.png",l="/ems_simulate/assets/iec104-parameter.BzPvxrIO.png",q=JSON.parse('{"title":"IEC 60870-5-104 操作指南","description":"","frontmatter":{},"headers":[],"relativePath":"guide/protocols/iec104/operation.md","filePath":"guide/protocols/iec104/operation.md","lastUpdated":1786981506000}'),i={name:"guide/protocols/iec104/operation.md"};function s(n,t,h,c,u,p){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="iec-60870-5-104-操作指南" tabindex="-1">IEC 60870-5-104 操作指南 <a class="header-anchor" href="#iec-60870-5-104-操作指南" aria-label="Permalink to &quot;IEC 60870-5-104 操作指南&quot;">​</a></h1><h2 id="一、前置条件" tabindex="-1">一、前置条件 <a class="header-anchor" href="#一、前置条件" aria-label="Permalink to &quot;一、前置条件&quot;">​</a></h2><ul><li>已安装并启动 EMS Simulate；</li><li><strong>服务端模拟</strong>：本机即可完成全流程演示；</li><li><strong>客户端模式</strong>：需要一台可访问的真实 IEC104 设备（或本软件再模拟一台服务端）。</li></ul><h2 id="二、服务端模式-模拟测控装置" tabindex="-1">二、服务端模式（模拟测控装置） <a class="header-anchor" href="#二、服务端模式-模拟测控装置" aria-label="Permalink to &quot;二、服务端模式（模拟测控装置）&quot;">​</a></h2><p><strong>目标</strong>：模拟一个 IEC104 服务端，响应主站的总召唤与数据上送。</p><h3 id="步骤-1-添加设备" tabindex="-1">步骤 1：添加设备 <a class="header-anchor" href="#步骤-1-添加设备" aria-label="Permalink to &quot;步骤 1：添加设备&quot;">​</a></h3><ol><li>点击&quot;<strong>添加设备</strong>&quot;；</li><li>填写设备名称（如 <code>IEC104 测控装置</code>）；</li><li>协议选择 <strong>IEC 60870-5-104</strong>；</li><li>连接方式选择 <strong>服务端（Server）</strong>；</li><li>设置监听端口（默认 2404），保存。</li></ol><h3 id="步骤-2-添加测点" tabindex="-1">步骤 2：添加测点 <a class="header-anchor" href="#步骤-2-添加测点" aria-label="Permalink to &quot;步骤 2：添加测点&quot;">​</a></h3><p>进入设备详情点击&quot;添加测点&quot;，IEC104 特有的配置项：</p><table tabindex="0"><thead><tr><th>配置项</th><th>说明</th></tr></thead><tbody><tr><td>测点类型</td><td>YC 遥测 / YX 遥信 / YK 遥控 / YT 遥调</td></tr><tr><td>IEC104 类型（ASDU）</td><td>如 <code>M_ME_NC_1</code> 短浮点遥测、<code>M_SP_NA_1</code> 单点遥信</td></tr><tr><td>信息体地址（IOA）</td><td>选择类型后自动分配起始地址偏移</td></tr><tr><td>品质描述符</td><td>溢出、闭锁、取代、不刷新、无效等品质位</td></tr><tr><td>乘法/加法系数</td><td>工程值换算（可选）</td></tr></tbody></table><blockquote><p>💡 平台按测点类型自动推荐可用 ASDU 类型列表，也支持按类型筛选测点。</p></blockquote><h3 id="步骤-3-启动设备" tabindex="-1">步骤 3：启动设备 <a class="header-anchor" href="#步骤-3-启动设备" aria-label="Permalink to &quot;步骤 3：启动设备&quot;">​</a></h3><p>点击&quot;<strong>开启设备</strong>&quot;，服务端开始监听 2404 端口并等待主站连接。</p><h3 id="步骤-4-验证" tabindex="-1">步骤 4：验证 <a class="header-anchor" href="#步骤-4-验证" aria-label="Permalink to &quot;步骤 4：验证&quot;">​</a></h3><ol><li>添加 IEC 104 <strong>客户端</strong>设备，目标指向本机 <code>127.0.0.1:2404</code>；</li><li>启动客户端，观察链路建立（STARTDT 激活）；</li><li>点击&quot;<strong>总召唤</strong>&quot;，验证服务端返回全部测点最新值；</li><li>修改服务端测点值（手动/模拟），观察客户端收到数据变化上送。</li></ol><p><img src="'+e+'" alt=""></p><h2 id="三、客户端模式-连接真实设备" tabindex="-1">三、客户端模式（连接真实设备） <a class="header-anchor" href="#三、客户端模式-连接真实设备" aria-label="Permalink to &quot;三、客户端模式（连接真实设备）&quot;">​</a></h2><ol><li>添加设备时连接方式选择 <strong>客户端（Client）</strong>，填写目标 IP 与端口（默认 2404）；</li><li>添加需要读取的测点：类型、ASDU、信息体地址与真实设备保持一致；</li><li>启动后客户端自动建立连接并激活链路；</li><li>可执行的操作： <ul><li><strong>总召唤</strong>：一次性获取全部测点最新值；</li><li><strong>时钟同步</strong>：下发时钟同步命令；</li><li><strong>遥控 / 遥调</strong>：下发单点/双点命令、设定值命令（需服务端支持）。</li></ul></li></ol><h2 id="四、协议参数详解" tabindex="-1">四、协议参数详解 <a class="header-anchor" href="#四、协议参数详解" aria-label="Permalink to &quot;四、协议参数详解&quot;">​</a></h2><p>在设备&quot;协议参数&quot;标签页可配置：</p><table tabindex="0"><thead><tr><th>参数</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td>发送窗口（k）</td><td>12</td><td>未确认 I 帧的最大数量</td></tr><tr><td>接收窗口（w）</td><td>8</td><td>接收确认阈值</td></tr><tr><td>t0（连接建立超时）</td><td>10s</td><td>TCP 连接建立超时</td></tr><tr><td>t1（报文确认超时）</td><td>15s</td><td>等待确认的 APDU 重发超时</td></tr><tr><td>t2（接收确认间隔）</td><td>10s</td><td>无数据时的确认发送间隔</td></tr><tr><td>t3（空闲检测间隔）</td><td>20s</td><td>空闲链路测试帧间隔</td></tr><tr><td>连接后总召唤</td><td>开</td><td>连接建立后自动执行总召唤</td></tr><tr><td>连接后计数量召唤</td><td>关</td><td>连接建立后执行计数量召唤</td></tr><tr><td>总召唤间隔</td><td>0</td><td>周期性总召唤间隔（0 不周期执行）</td></tr><tr><td>时钟同步周期</td><td>0</td><td>周期性时钟同步间隔（0 不周期执行）</td></tr><tr><td>源发站地址</td><td>0</td><td>报文公共地址（COA）</td></tr></tbody></table><blockquote><p><img src="'+l+'" alt=""></p><p>💡 遥调-遥测绑定：可将遥调点绑定到遥测点，遥调下发时自动更新对应遥测值（模拟调节量）。</p></blockquote><h2 id="五、常见问题" tabindex="-1">五、常见问题 <a class="header-anchor" href="#五、常见问题" aria-label="Permalink to &quot;五、常见问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>排查建议</th></tr></thead><tbody><tr><td>链路建立失败</td><td>确认端口、IP、t0 超时是否合理</td></tr><tr><td>总召唤无数据</td><td>确认服务端已添加测点并启动</td></tr><tr><td>遥控/遥调无响应</td><td>确认命令类型与 ASDU 匹配（单点/双点/设定值）</td></tr><tr><td>数据品质为无效</td><td>检查测点品质描述符配置（IV 位）</td></tr></tbody></table><blockquote><p>📄 报文如何解析见 <a href="./packet-view.html">IEC104 报文查看</a>。</p></blockquote>',25)])])}const g=d(i,[["render",s]]);export{q as __pageData,g as default};
